const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
let cached = null;

export function goatImageBytes() {
  if (cached) return cached;
  const clean = GOAT_IMAGE_BASE64.replace(/[^A-Za-z0-9+/=]/g, '');
  const padding = clean.endsWith('==') ? 2 : clean.endsWith('=') ? 1 : 0;
  const bytes = new Uint8Array((clean.length * 3) / 4 - padding);
  let p = 0;
  for (let i = 0; i < clean.length; i += 4) {
    const a = ALPHABET.indexOf(clean[i]);
    const b = ALPHABET.indexOf(clean[i + 1]);
    const c = clean[i + 2] === '=' ? 0 : ALPHABET.indexOf(clean[i + 2]);
    const d = clean[i + 3] === '=' ? 0 : ALPHABET.indexOf(clean[i + 3]);
    const triple = (a << 18) | (b << 12) | (c << 6) | d;
    bytes[p++] = (triple >> 16) & 255;
    if (clean[i + 2] !== '=') bytes[p++] = (triple >> 8) & 255;
    if (clean[i + 3] !== '=') bytes[p++] = triple & 255;
  }
  cached = bytes;
  return cached;
}

